namespace UnityEngine{public static class Mathf{public static float Max(float a,float b)=>Math.Max(a,b);public static float Clamp(float v,float a,float b)=>Math.Max(a,Math.Min(b,v));public static float Clamp01(float v)=>Clamp(v,0,1);public static float Abs(float v)=>Math.Abs(v);public static int RoundToInt(float v)=>(int)Math.Round(v);}}
public sealed class ItemClass{public string Name;public string GetItemName()=>Name;}
public sealed class ItemValue{public ItemClass ItemClass;public float UseTimes;public int Seed=741,Meta=19;public Dictionary<string,object> Metadata=new Dictionary<string,object>();public bool IsEmpty()=>ItemClass==null;public bool HasMetadata(string key)=>Metadata.ContainsKey(key);public bool TryGetMetadata<T>(string key,out T value){value=default;if(!Metadata.TryGetValue(key,out var obj)||!(obj is T actual))return false;value=actual;return true;}public void SetMetadata<T>(string key,T value)=>Metadata[key]=value;}
public sealed class RebirthConsumableDefinition{public bool IsDrink=true;public float ContainerCapacityMl=725,InitialVolumeMl=725;public string LiquidProfile="unsafeWater";}
