 RebirthLiquidContainerService.SetRemainingMl(old,d,600);Check(RebirthLiquidContainerService.GetRemainingMl(old,d)==600&&old.UseTimes==125,"intentional consume stays partial");Check(!RebirthCookingItemStats.FullIngredient(old),"actual gate still refuses deliberately partial ingredient");RebirthLiquidContainerService.SetRemainingMl(old,d,0);Check(RebirthLiquidContainerService.GetRemainingMl(old,d)==0,"empty consumed murky never refills");
 var direct=Murky();RebirthLiquidContainerService.SetRemainingMl(direct,d,300);Check(RebirthLiquidContainerService.GetRemainingMl(direct,d)==300,"direct intentional volume write stamps migration");
 var full=Murky();full.SetMetadata(RebirthLiquidContainerService.VolumeKey,725f);Check(RebirthLiquidContainerService.NormalizeState(full,d,out volume)&&volume==725,"legacy already full idempotent volume");Check((int)full.Metadata[RebirthLiquidContainerService.MurkyFullInitializationKey]==1,"full migration marker written");
 var clean=new ItemValue{ItemClass=new ItemClass{Name="drinkJarBoiledWater"},UseTimes=400};clean.SetMetadata(RebirthLiquidContainerService.VolumeKey,125f);Check(RebirthLiquidContainerService.GetRemainingMl(clean,d)==125&&!clean.HasMetadata(RebirthLiquidContainerService.MurkyFullInitializationKey),"unrelated drink volume unchanged");var legacyClean=new ItemValue{ItemClass=clean.ItemClass,UseTimes=400};Check(RebirthLiquidContainerService.GetRemainingMl(legacyClean,d)==325,"ordinary legacy degradation fallback unchanged");
 Console.WriteLine("PASS "+checks+" actual liquid/gate source checks; native loot XML and real item/save behavior require parent validation.");}
